  const lc = col(P.color), wc = col(P.wall);
  const room = new THREE.Mesh(new THREE.BoxGeometry(12, 4, 12), new THREE.MeshBasicMaterial({ color: wc, side: THREE.BackSide }));
  room.position.y = 2; s.add(room);
  const floor = new THREE.Mesh(new THREE.PlaneGeometry(12, 12), new THREE.MeshBasicMaterial({ color: wc.clone().multiplyScalar(0.6) })); floor.rotation.x = -Math.PI / 2; floor.position.y = 0.01; s.add(floor);
  const strip = new THREE.MeshBasicMaterial({ color: lc.clone().multiplyScalar(P.intensity ?? 6) });
  for (let i = -2; i <= 2; i++) { const m = new THREE.Mesh(new THREE.PlaneGeometry(0.5, 9), strip); m.rotation.x = Math.PI / 2; m.position.set(i * 2.2, 3.98, 0); s.add(m); }
  const win = new THREE.Mesh(new THREE.PlaneGeometry(10, 2.4), new THREE.MeshBasicMaterial({ color: col(P.window ?? 0x9fb8d8).multiplyScalar(P.windowIntensity ?? 1.5) }));
  win.position.set(0, 2, -5.98); s.add(win);
