  const U = fogUniforms({ uT: shared.time, uW: { value: Wd }, uCol: { value: col(o.color ?? 0xdfeaea) }, uAmb: { value: col(o.ambient ?? 0x8090a0) }, uSun: shared.sunColor, uSunD: shared.sunDir, uSpeed: { value: o.speed ?? 1 } });
